const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');

const SECRET = process.env.JWT_SECRET_KEY;
const ALGORITHM = process.env.JWT_ALGORITHM || 'HS256';
const ACCESS_EXPIRE = `${process.env.JWT_ACCESS_TOKEN_EXPIRE_MINUTES || 30}m`;
const REFRESH_EXPIRE = `${process.env.JWT_REFRESH_TOKEN_EXPIRE_DAYS || 7}d`;

const hashPassword = (pw) => bcrypt.hash(pw, 10);
const verifyPassword = (pw, hash) => bcrypt.compare(pw, hash);
const createAccessToken = (subject) => jwt.sign({ sub: subject, type: 'access' }, SECRET, { algorithm: ALGORITHM, expiresIn: ACCESS_EXPIRE });
const createRefreshToken = (subject) => jwt.sign({ sub: subject, type: 'refresh' }, SECRET, { algorithm: ALGORITHM, expiresIn: REFRESH_EXPIRE });

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token' });
  try {
    const payload = jwt.verify(token, SECRET);
    req.user = payload.sub;
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};
